91	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
92	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
93	// from deep inside the engine. Both directions. Returns "" when they agree, when
94	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
95	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
96	std::string elf_engine_arch_error(const std::string& elf,
97	                                  const EngineDescriptor& eng) {
98	  const int ex = elf_xlen(elf);
99	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
100	  char buf[256];
101	  std::snprintf(buf, sizeof(buf),
102	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
103	                "or an rv%d ELF",
104	                ex, eng.id.c_str(), eng.xlen, ex);
105	  return buf;
106	}
