108	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
109	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
110	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
111	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
112	// reports the plan, it does not run it.
113	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
114	                  const std::vector<std::string>& labels) {
115	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
116	  for (size_t i = 0; i < argvs.size(); ++i) {
117	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
118	                labels[i].c_str());
119	    std::printf("%s\n", render_argv(argvs[i]).c_str());
120	  }
121	  return 0;
122	}
